draw:
var v = 343;
var vs = p.speed;
var T = 1;
var y0 = H * 0.5;
var Wm = 2 * v * T * 2.25;
var sc = (W - 24) / Wm;
var cx0 = W / 2 - vs * T * sc;

ctx.font = '12px ui-sans-serif, system-ui, sans-serif';
ctx.lineWidth = 1;

// axis
ctx.strokeStyle = C.faint;
ctx.beginPath();
ctx.moveTo(0, y0);
ctx.lineTo(W, y0);
ctx.stroke();

// three crests: emitted at 0, T, 2T ; now is 2T
var i;
for (i = 0; i < 3; i++) {
  var r = v * (2 - i) * T * sc;
  var cx = cx0 + vs * i * T * sc;
  ctx.strokeStyle = i === 2 ? C.accent : C.rule;
  ctx.beginPath();
  ctx.arc(cx, y0, Math.max(r, 1), 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = C.figure;
  ctx.beginPath();
  ctx.arc(cx, y0, 2.5, 0, Math.PI * 2);
  ctx.fill();
}

// source now
var sxNow = cx0 + vs * 2 * T * sc;
ctx.fillStyle = C.accent;
ctx.beginPath();
ctx.arc(sxNow, y0, 5, 0, Math.PI * 2);
ctx.fill();
ctx.fillStyle = C.ink;
ctx.fillText('source now', sxNow - 30, y0 - 12);

// ahead gap markers
var aheadOuter = sxNow + (v * T - vs * T) * sc;
var yA = y0 + 34;
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(sxNow, y0);
ctx.lineTo(sxNow, yA + 6);
ctx.moveTo(aheadOuter, y0);
ctx.lineTo(aheadOuter, yA + 6);
ctx.moveTo(sxNow, yA);
ctx.lineTo(aheadOuter, yA);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText('ahead: (v - vs)T = ' + ((v - vs) * T).toFixed(0) + ' m', sxNow - 20, yA + 20);

// behind gap markers
var behindOuter = sxNow - (v * T + vs * T) * sc;
var yB = y0 - 40;
ctx.strokeStyle = C.figure;
ctx.beginPath();
ctx.moveTo(sxNow, y0);
ctx.lineTo(sxNow, yB - 6);
ctx.moveTo(behindOuter, y0);
ctx.lineTo(behindOuter, yB - 6);
ctx.moveTo(sxNow, yB);
ctx.lineTo(behindOuter, yB);
ctx.stroke();
ctx.fillStyle = C.ink;
ctx.fillText('behind: (v + vs)T = ' + ((v + vs) * T).toFixed(0) + ' m', behindOuter + 8, yB - 10);

ctx.fillStyle = C.faint;
ctx.fillText('drawn for T = 1 s, v = 343 m/s', 8, H - 8);

out.note = 'source speed ' + vs.toFixed(0) + ' m/s: wavelength ahead ' + ((v - vs) * T).toFixed(0) + ' m, behind ' + ((v + vs) * T).toFixed(0) + ' m';
